{
  "title": "Weekly report CSV export",
  "open_questions": [
    {
      "id": "export-trigger",
      "question": "How should the export be triggered — a button on the report page, a URL parameter, a menu item, or something else?",
      "required": true
    },
    {
      "id": "csv-filename",
      "question": "What filename should the downloaded CSV have (e.g. weekly-report-YYYY-MM-DD.csv or a fixed name)?",
      "required": false
    },
    {
      "id": "column-headers",
      "question": "Should the CSV include a header row, and if so should the header labels match the on-screen column names exactly?",
      "required": true
    },
    {
      "id": "date-range",
      "question": "Which week does the report cover — the current calendar week, the last 7 days, or a user-selected range — and should that be reflected in the export?",
      "required": true
    },
    {
      "id": "auth-required",
      "question": "Must the export endpoint enforce the same authentication and authorisation as the report page?",
      "required": true
    },
    {
      "id": "character-encoding",
      "question": "Should the CSV be UTF-8? Does it need a BOM for Excel compatibility?",
      "required": false
    },
    {
      "id": "empty-report",
      "question": "What should be exported when the report has no rows — an empty file, headers only, or an error?",
      "required": false
    },
    {
      "id": "existing-test-files",
      "question": "Which existing test files cover the report view so gate_bindings can reference them rather than new files?",
      "required": true
    }
  ],
  "criteria": [
    {
      "id": "csv-content-type",
      "title": "Export response has Content-Type text/csv",
      "guidance": "Send a request to the export endpoint and assert the response Content-Type header is text/csv (or text/csv; charset=utf-8).",
      "required": true,
      "human": false
    },
    {
      "id": "csv-disposition",
      "title": "Response triggers a file download",
      "guidance": "Assert the response includes a Content-Disposition header with attachment and a filename ending in .csv.",
      "required": true,
      "human": false
    },
    {
      "id": "row-parity",
      "title": "CSV contains exactly the same rows as the report, in the same order",
      "guidance": "Fetch the report data and the CSV for the same period; parse both and assert row count and row order are identical.",
      "required": true,
      "human": false
    },
    {
      "id": "column-parity",
      "title": "CSV columns match the report columns",
      "guidance": "Parse the CSV header row and assert it contains every column the report displays, in the same left-to-right order.",
      "required": true,
      "human": false
    },
    {
      "id": "valid-csv-format",
      "title": "Output is valid RFC 4180 CSV",
      "guidance": "Parse the response body with a strict CSV parser (e.g. Python csv module) and assert no parse errors; check that fields containing commas or quotes are properly quoted.",
      "required": true,
      "human": false
    },
    {
      "id": "no-regression-report-page",
      "title": "Existing report page continues to render correctly after the change",
      "guidance": "Run the existing test suite; all previously passing report-related tests must still pass.",
      "required": true,
      "human": false
    },
    {
      "id": "export-discoverable",
      "title": "The export action is visible and clearly labelled on the report page",
      "guidance": "A person reviews the report page and confirms the export control is present, labelled in plain language (e.g. 'Export CSV'), and easy to find without instructions.",
      "required": true,
      "human": true
    }
  ],
  "gates": [
    {
      "id": "test",
      "run": "pytest -q"
    }
  ],
  "gate_bindings": [
    {
      "id": "bind-no-regression",
      "run": "pytest -q",
      "proves": "no-regression-report-page"
    }
  ],
  "tasks": [
    {
      "id": "csv-export-endpoint",
      "brief": "briefs/csv-export-endpoint.md",
      "dir": ".",
      "objective": "Add a backend endpoint (or view) that accepts a request for the weekly report in CSV format and returns a response with Content-Type text/csv, a Content-Disposition attachment header with a .csv filename, and a body that is valid RFC 4180 CSV whose rows and columns match exactly what the existing report view renders, in the same order."
    },
    {
      "id": "csv-export-ui",
      "brief": "briefs/csv-export-ui.md",
      "dir": ".",
      "objective": "Add a clearly labelled export control (e.g. an 'Export CSV' button or link) to the weekly report page that triggers a download from the new endpoint. The control must be visible without scrolling on a typical desktop viewport and must not break any existing report page behaviour."
    }
  ]
}
